pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(new Log()));
        amount = bound(amount, 1 wei, 100 ether);
        // timestamp at the moment of the Put call
        uint256 ts = block.timestamp + 1;
        vm.warp(ts);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        // General rule: after any successful Put, the stored unlock time is >= the
        // block timestamp at which the Put was executed.
        assertTrue(c.Acc(actor).unlockTime >= ts);
    }
}

