pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(address actor, uint256 amount, uint256 t) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);
        t = bound(t, 0, type(uint256).max / 2);
        uint256 ts0 = block.timestamp;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        // Jump to max(t, ts0): in P the unlock time is exactly this value and
        // Collect requires a strictly later block, so Collect must fail here.
        uint256 w = t > ts0 ? t : ts0;
        vm.warp(w);
        vm.prank(actor);
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

