pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();          // kept a handle so History is observable (Log's getters are public)
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1000 ether);
        uint256 beforeLen = log.History_length();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, uint256(0)));
        assertTrue(ok);

        // General rule: any successful Put of `amount` appends one History entry whose Val equals `amount`.
        assertTrue(
            log.History_length() == beforeLen + 1 && log.History(beforeLen).Val == amount,
            "successful Put must log exactly one entry with the deposited amount"
        );
    }
}

