pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public { lg = new Log(); c = new C(address(lg)); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1e30);
        vm.deal(actor, amount);
        uint256 beforeLen = historyLength();
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, block.timestamp + 1));
        assertTrue(ok && historyLength() == beforeLen + 1 && lastVal() == amount);
    }

    function historyLength() internal view returns (uint256 n) {
        for (uint256 i = 0; ; i++) {
            try lg.History(i) { n = i + 1; } catch { break; }
        }
    }

    function lastVal() internal view returns (uint256) {
        return lg.History(historyLength() - 1).Val;
    }
}

