contract InvMutTest {
    C c;
    Log log;

    constructor(C _c, Log _l) {
        c = _c;
        log = _l;
    }

    receive() external payable {}

    function run(uint putAmt, uint collectAmt) public {
        require(putAmt >= 1 ether);
        require(collectAmt > 0 && collectAmt < putAmt);
        require(address(this).balance >= putAmt);

        c.Put{value: putAmt}(0);
        // a later transaction: time has advanced past the unlock time
        c.Collect(collectAmt);

        uint len = log.History().length;
        require(len > 0);
        (,, uint val,) = log.History(len - 1);
        assert(val == collectAmt);
    }
}

