contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint putAmt, uint amt, uint amt2) public payable {
        require(putAmt >= 1 ether && amt <= putAmt && amt2 <= putAmt && amt > putAmt - 1 ether);
        c.Put{value: putAmt}(0);
        bool ok1;
        try c.Collect(amt) { ok1 = true; } catch { ok1 = false; }
        require(ok1);
        bool ok2;
        try c.Collect(amt2) { ok2 = true; } catch { ok2 = false; }
        assert(!ok2);
    }
