contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint unlockTime, uint amount) public payable {
        require(address(this).balance >= deposit);
        require(deposit >= 1 ether);
        require(amount >= 1 ether && amount <= deposit);
        require(unlockTime <= block.timestamp);
        c.Put{value: deposit}(unlockTime);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}
